import {AuthConfig, buildClient, registerInstances} from 'webcommander-sdk';

registerInstances([
    new AuthConfig({
        clientName: 'default',
        grantType: 'client_credentials',
        baseUrl: process.env.WC_BASE_URL,
        clientId: process.env.WC_CLIENT_ID,
        clientSecret: process.env.WC_CLIENT_SECRET,
        redirectUri: process.env.WC_REDIRECT_URI,
        authString: process.env.WC_AUTH_STRING,
    }),
]);

const client = await buildClient(0, {raiseOnError: true});

const response = await client.adminCustomers.getCustomers({limit: 20, status: 'active'});
for (const customer of response.map.customers) {
    console.log(customer.customer_id, customer.email);
}

import com.webcommander.sdk.client.ApiResponse;
import com.webcommander.sdk.client.WebCommanderClient;
import com.webcommander.sdk.config.AuthConfig;
import com.webcommander.sdk.config.SdkConfig;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) throws Exception {
        AuthConfig auth = AuthConfig.builder()
                .baseUrl(System.getenv("WC_BASE_URL"))
                .clientId(System.getenv("WC_CLIENT_ID"))
                .clientSecret(System.getenv("WC_CLIENT_SECRET"))
                .redirectUri(System.getenv("WC_REDIRECT_URI"))
                .authString(System.getenv("WC_AUTH_STRING"))
                .clientName("default")
                .build();
        SdkConfig config = SdkConfig.builder(auth).raiseOnError(true).build();
        WebCommanderClient client = new WebCommanderClient(config);

        ApiResponse response = client.adminCustomers().getCustomers(Map.of("limit", 20, "status", "active"));
        Map<?, ?> body = (Map<?, ?>) response.getMap();
        for (Object row : (List<?>) body.get("customers")) {
            Map<?, ?> customer = (Map<?, ?>) row;
            System.out.println(customer.get("customer_id") + " " + customer.get("email"));
        }
    }
}

